"use client";

import { useMemo, type ReactNode } from "react";
import { ArrowDown, ArrowUp, Minus, TrendingDown, TrendingUp, User } from "lucide-react";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
  useDataGridSortState,
} from "@/registry/default/components/data-grid/data-grid";
import { generateDemoRows, type DemoRow } from "./demo-data";

/**
 * The sort-direction state icon: reads live grid state, so clicking the header (sort mode)
 * cycles unsorted -> asc -> desc and this icon follows: a muted minus when unsorted, an up
 * icon when ascending, a down icon when descending.
 */
function SortStateIcon(props: { columnId: string; unsorted: ReactNode; asc: ReactNode; desc: ReactNode }): ReactNode {
  const sortState = useDataGridSortState();
  const entry = sortState.find((spec) => spec.columnId === props.columnId);
  const stateIcon = entry?.direction === "asc" ? props.asc : entry?.direction === "desc" ? props.desc : props.unsorted;
  return <span className="flex shrink-0 items-center">{stateIcon}</span>;
}

const unsortedIcon = <Minus className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />;

const columns = defineColumns<DemoRow>()([
  {
    id: "name",
    sortIndicator: false,
    header: (
      <span className="flex items-center gap-1.5">
        <User className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />
        Name
        <SortStateIcon
          columnId="name"
          unsorted={unsortedIcon}
          asc={<ArrowUp className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />}
          desc={<ArrowDown className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />}
        />
      </span>
    ),
    accessorKey: "name",
    type: "text",
    width: 150,
  },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 140 },
  {
    id: "score",
    sortIndicator: false,
    header: (
      <span className="flex items-center gap-1.5">
        Logins (30 days)
        <SortStateIcon
          columnId="score"
          unsorted={unsortedIcon}
          asc={<TrendingUp className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />}
          desc={<TrendingDown className="size-3.5 shrink-0 text-muted-foreground" aria-hidden="true" />}
        />
      </span>
    ),
    accessorKey: "score",
    type: "number",
    width: 90,
  },
] as const);

/**
 * `ColumnDef.header` takes a component, not just a string: the header subscribes to live grid
 * state and re-renders when it changes. In `sort` header-click mode a custom header owns its
 * display (the built-in arrow is only appended to string headers, like Email's).
 */
export default function DataGridCustomHeadersDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(10), []);

  return (
    <div className="w-full flex h-[360px] flex-col gap-2">
      <span className="text-sm text-muted-foreground">
        Click the Name or Logins header to sort: a minus means unsorted, an up icon ascending, a down icon descending.
      </span>
      <div className="min-h-0 flex-1 overflow-hidden rounded-md border border-border">
        <DataGridProvider defaultData={rows} columns={columns} headerClickBehavior="sort">
          <DataGridRoot className="h-full rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const FIRST_NAMES = [
  "Ava", "Liam", "Mia", "Noah", "Priya", "Mateo", "Yuki", "Omar", "Elena", "Kofi",
  "Sofia", "Ravi", "Hannah", "Diego", "Amara", "Lukas", "Nadia", "Tomas", "Ingrid", "Jamal",
  "Chloe", "Arjun", "Fatima", "Ethan", "Leila", "Marco", "Zara", "Felix", "Mei", "Jonas",
  "Aisha", "Pavel", "Clara", "Hugo", "Nina", "Samir", "Alma", "Oskar", "Lucia", "Dev",
] as const;
const LAST_NAMES = [
  "Becker", "Okafor", "Nguyen", "Lindqvist", "Alvarez", "Tanaka", "Haddad", "Moreau", "Kowalski", "Joshi",
  "Rossi", "Teixeira", "Novak", "Fischer", "Mensah", "Larsen", "Castillo", "Ivanov", "Yamamoto", "Duarte",
  "Brennan", "Hoffmann", "Santos", "Kaya", "Weber", "Adeyemi", "Petrov", "Lopez", "Chen", "Murphy",
  "Bianchi", "Hartmann", "Ito", "Reyes", "Sorensen", "Qureshi", "Ferraz", "Dubois", "Park", "Svensson",
] as const;

/**
 * Generates `count` deterministic rows of a fictional user directory (seed 42, stable across renders).
 * `score` is the number of logins in the last 30 days.
 */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  const emailUses = new Map<string, number>();
  for (let i = 0; i < count; i++) {
    const first = FIRST_NAMES[Math.floor(next() * FIRST_NAMES.length)]!; // fixed non-empty literal arrays
    const last = LAST_NAMES[Math.floor(next() * LAST_NAMES.length)]!;
    const handle = `${first}.${last}`.toLowerCase();
    const uses = (emailUses.get(handle) ?? 0) + 1;
    emailUses.set(handle, uses);
    rows.push({
      id: `row-${i}`,
      name: `${first} ${last}`,
      email: `${handle}${uses > 1 ? uses : ""}@example.com`,
      age: Math.floor(next() * 44) + 21,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
